package com.supermarkettracker.infrastructure.persistence.entity;
import com.supermarkettracker.domain.model.enums.StatusVenda;
import jakarta.persistence.*; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="venda") public class VendaEntity { @Id public UUID id; @Column(name="empresa_id",nullable=false) public UUID empresaId; @Column(name="loja_id",nullable=false) public UUID lojaId; @Column(name="sessao_caixa_id") public UUID sessaoCaixaId; @Column(name="usuario_id",nullable=false) public UUID usuarioId; @Column(name="cliente_id") public UUID clienteId; @Column(nullable=false) public long numero; @Column(nullable=false,precision=14,scale=2) public BigDecimal subtotal; @Column(nullable=false,precision=14,scale=2) public BigDecimal desconto; @Column(nullable=false,precision=14,scale=2) public BigDecimal acrescimo; @Column(nullable=false,precision=14,scale=2) public BigDecimal total; @Column(name="custo_total",nullable=false,precision=14,scale=2) public BigDecimal custoTotal; @Column(nullable=false,precision=14,scale=2) public BigDecimal lucro; @Column(nullable=false,precision=14,scale=2) public BigDecimal prejuizo; @Column(name="quantidade_itens",nullable=false,precision=14,scale=3) public BigDecimal quantidadeItens; @Enumerated(EnumType.STRING) @JdbcTypeCode(SqlTypes.NAMED_ENUM) @Column(nullable=false,columnDefinition="status_venda") public StatusVenda status; @Column(name="finalizada_em") public Instant finalizadaEm; @Column(name="cancelada_em") public Instant canceladaEm; @Column(name="motivo_cancelamento") public String motivoCancelamento; public String observacao; @Column(name="created_at",nullable=false) public Instant criadoEm; @Column(name="updated_at",nullable=false) public Instant atualizadoEm; public VendaEntity() {} }
